import{_ as o,o as i,c as a,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Ley Antimonopolio","description":"","frontmatter":{},"headers":[],"relativePath":"es/47-反垄断法.md","filePath":"es/47-反垄断法.md","lastUpdated":null}'),n={name:"es/47-反垄断法.md"};function t(l,e,r,c,d,p){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="ley-antimonopolio" tabindex="-1">Ley Antimonopolio <a class="header-anchor" href="#ley-antimonopolio" aria-label="Permalink to &quot;Ley Antimonopolio&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>47</td></tr><tr><td>Módulo</td><td>Sistema Legal y Marco de Gobernanza</td></tr><tr><td>Palabras clave</td><td>Antimonopolio, Competencia leal, Orden simbiótico del mercado, Prohibición de conductas depredadoras, Garantía del avance conjunto de las Diez Mil Razas</td></tr></tbody></table><h2 id="i-proposito-legislativo-y-principios-basicos" tabindex="-1">I. Propósito Legislativo y Principios Básicos <a class="header-anchor" href="#i-proposito-legislativo-y-principios-basicos" aria-label="Permalink to &quot;I. Propósito Legislativo y Principios Básicos&quot;">​</a></h2><p>La <em>Ley Antimonopolio</em> es una de las cinco leyes complementarias de la Civilización Simbiótica del Ancla. Su objetivo es prevenir las conductas de monopolio y depredación en los recursos de cultivo, las sectas de cultivo, los mercados comerciales y otros ámbitos, mantener la competencia leal y el orden simbiótico del mercado del Universo Hengyuan, y garantizar el &quot;avance conjunto de las Diez Mil Razas&quot; asegurando que ninguna fuerza u organización pueda apoderarse de las oportunidades de desarrollo mediante el monopolio.</p><p>Esta Ley establece los siguientes principios básicos:</p><table tabindex="0"><thead><tr><th>Principio</th><th>Contenido</th></tr></thead><tbody><tr><td>Competencia Leal</td><td>Todos los sujetos compiten en igualdad de condiciones; se prohíben el abuso de posición dominante y la competencia desleal</td></tr><tr><td>Mercado Abierto</td><td>Se prohíben los acuerdos monopolísticos, la división del mercado y las restricciones a la competencia que excluyan o limiten la competencia</td></tr><tr><td>Protección del Débil</td><td>Protección inclinada hacia los nuevos cultivadores, las razas principiantes y las organizaciones pequeñas y medianas</td></tr><tr><td>Orden Simbiótico</td><td>El mercado debe servir al avance conjunto de las Diez Mil Razas; se prohíbe el saqueo de los intereses públicos por el capital y el poder</td></tr><tr><td>Aplicación Unificada</td><td>La aplicación antimonopolio se realiza por una institución unificada; se prohíben el proteccionismo local y las conductas monopolísticas transplanares</td></tr></tbody></table><h2 id="ii-definicion-de-monopolio" tabindex="-1">II. Definición de Monopolio <a class="header-anchor" href="#ii-definicion-de-monopolio" aria-label="Permalink to &quot;II. Definición de Monopolio&quot;">​</a></h2><p>Esta Ley define los siguientes actos como actos monopolísticos, que quedan prohibidos:</p><ol><li><strong>Acuerdos Monopolísticos</strong>: Acuerdos entre competidores o entre empresas aguas arriba y aguas abajo para fijar precios, dividir mercados, restringir la producción, boicotear, etc.</li><li><strong>Abuso de Posición Dominante</strong>: El abuso de una posición dominante en el mercado para vender a precios injustamente altos, vender por debajo del costo, imponer condiciones comerciales irrazonables, negarse a negociar, ventas atadas, etc.</li><li><strong>Concentración de Operadores</strong>: Fusiones, adquisiciones y empresas conjuntas que eliminen o restrinjan la competencia, con declaración previa a la autoridad antimonopolio para su revisión.</li><li><strong>Monopolio Administrativo</strong>: El abuso del poder administrativo por órganos estatales y organizaciones públicas para restringir la competencia, el proteccionismo local y el monopolio industrial.</li><li><strong>Monopolio de Recursos de Cultivo</strong>: El control monopolístico de los recursos de cultivo, los nodos de energía espiritual y los reinos secretos, excluyendo a otros del cultivo.</li><li><strong>Monopolio de Talentos</strong>: El uso de medios desleales para controlar exclusivamente los talentos de cultivo, restringiendo la libre circulación de talentos.</li></ol><h2 id="iii-instituciones-antimonopolio" tabindex="-1">III. Instituciones Antimonopolio <a class="header-anchor" href="#iii-instituciones-antimonopolio" aria-label="Permalink to &quot;III. Instituciones Antimonopolio&quot;">​</a></h2><p>El Tribunal Simbiótico y sus instituciones de aplicación antimonopolio afiliadas ejercen las siguientes funciones:</p><table tabindex="0"><thead><tr><th>Institución</th><th>Función</th></tr></thead><tbody><tr><td>Oficina de Aplicación Antimonopolio</td><td>Investiga actos monopolísticos, inicia investigaciones sobre actos sospechosos de monopolio</td></tr><tr><td>Comité de Revisión de Monopolio</td><td>Revisa la concentración de operadores y los cambios en la estructura del mercado</td></tr><tr><td>Oficina de Supervisión de Precios</td><td>Supervisa el comportamiento de precios de los recursos de cultivo y mercancías importantes</td></tr><tr><td>Oficina de Coordinación Transplanar</td><td>Coordina la aplicación antimonopolio entre planos, evitando monopolios transplanares</td></tr></tbody></table><p>La institución de aplicación antimonopolio goza de facultades de investigación: puede exigir explicaciones a las partes relevantes, inspeccionar libros y registros, sellar y confiscar pruebas, etc. Las partes investigadas deben cooperar y no deben negarse ni obstruir.</p><h2 id="iv-disposiciones-especiales-sobre-el-monopolio-de-recursos-de-cultivo" tabindex="-1">IV. Disposiciones Especiales sobre el Monopolio de Recursos de Cultivo <a class="header-anchor" href="#iv-disposiciones-especiales-sobre-el-monopolio-de-recursos-de-cultivo" aria-label="Permalink to &quot;IV. Disposiciones Especiales sobre el Monopolio de Recursos de Cultivo&quot;">​</a></h2><p>Los recursos de cultivo son riqueza pública del Universo Hengyuan; esta Ley establece disposiciones especiales sobre su prevención del monopolio:</p><ol><li><strong>Igualdad de Acceso a Recursos</strong>: Todas las razas y cultivadores tienen iguales derechos de acceso a los recursos de cultivo; ninguna secta u organización puede ocupar exclusivamente los recursos centrales.</li><li><strong>Compartición de Nodos de Energía Espiritual</strong>: Los nodos clave de energía espiritual implementan un sistema de gestión compartida; se prohíben la ocupación exclusiva y el establecimiento de enclaves de cultivo privados.</li><li><strong>Sistema Abierto de Reinos Secretos</strong>: Los reinos secretos descubiertos por cualquier sujeto deben ser reportados a la institución de gestión e incorporados al sistema de recursos públicos; se prohíbe la ocupación secreta.</li><li><strong>Regulación del Mercado de Píldoras</strong>: Las píldoras importantes y medicinas espirituales implementan orientación de precios y supervisión del suministro; se prohíben el acaparamiento y la especulación de precios.</li><li><strong>Supervisión de la Circulación de Artefactos</strong>: La circulación de artefactos de alto nivel debe registrarse y gestionarse; se prohíbe el establecimiento de un monopolio de artefactos armados mediante el control de las fuentes de artefactos.</li></ol><h2 id="v-remedios-y-responsabilidad-legal" tabindex="-1">V. Remedios y Responsabilidad Legal <a class="header-anchor" href="#v-remedios-y-responsabilidad-legal" aria-label="Permalink to &quot;V. Remedios y Responsabilidad Legal&quot;">​</a></h2><p>Por los actos monopolísticos, esta Ley prevé los siguientes remedios y responsabilidades:</p><ul><li><strong>Orden de Cese</strong>: La institución de aplicación antimonopolio ordena el cese de los actos monopolísticos.</li><li><strong>Multas</strong>: Se imponen multas según las ganancias ilegales y la gravedad de las circunstancias.</li><li><strong>Decomiso de Ganancias Ilegales</strong>: Las ganancias ilegales obtenidas mediante actos monopolísticos son confiscadas.</li><li><strong>Revocación de Cualificaciones</strong>: En casos graves, se revocan las licencias comerciales o las cualificaciones de las sectas de cultivo.</li><li><strong>Indemnización de Daños</strong>: Las víctimas de actos monopolísticos tienen derecho a reclamar indemnización por daños.</li><li><strong>Responsabilidad Penal</strong>: Si un acto monopolístico constituye delito, se persigue responsabilidad penal.</li></ul><h2 id="vi-accion-de-interes-publico" tabindex="-1">VI. Acción de Interés Público <a class="header-anchor" href="#vi-accion-de-interes-publico" aria-label="Permalink to &quot;VI. Acción de Interés Público&quot;">​</a></h2><p>Por los actos monopolísticos que dañen los intereses públicos, los siguientes sujetos pueden presentar acciones de interés público antimonopolio ante el Tribunal Simbiótico:</p><ul><li>Las instituciones de aplicación antimonopolio</li><li>Las organizaciones de interés público simbióticas</li><li>Otros sujetos previstos por la ley</li></ul><p>La acción de interés público tiene como objetivo detener los actos monopolísticos, proteger el interés público del orden del mercado y compensar los daños causados al interés público.</p><h2 id="vii-aplicacion-de-la-ley" tabindex="-1">VII. Aplicación de la Ley <a class="header-anchor" href="#vii-aplicacion-de-la-ley" aria-label="Permalink to &quot;VII. Aplicación de la Ley&quot;">​</a></h2><p>Esta Ley se aplica a todos los actos monopolísticos que ocurran dentro del Universo Hengyuan, incluidos los actos monopolísticos de sujetos de otros universos bajo la jurisdicción del Universo Hengyuan. Para los actos monopolísticos que ocurran a través de universos, se aplica el principio de reciprocidad y consulta.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La <em>Ley Antimonopolio</em> es el baluarte legal de la filosofía de &quot;avance conjunto de las Diez Mil Razas&quot; de la Civilización Simbiótica del Ancla. Al definir y sancionar los actos monopolísticos, establecer instituciones dedicadas y regular el monopolio de los recursos de cultivo, garantiza la equidad y apertura del mercado simbiótico, impide que cualquier fuerza saquee los recursos y las oportunidades de desarrollo, y proporciona garantías institucionales para el avance conjunto de las Diez Mil Razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitución Simbiótica: Principios Generales)</li><li>42-消费者保护法 (Ley de Protección al Consumidor)</li><li>41-共生劳动法 (Ley Simbiótica del Trabajo)</li><li>07-联产承包机制详解 (Explicación Detallada del Mecanismo de Contratación Conjunta de Producción)</li></ul>',29)])])}const b=o(n,[["render",t]]);export{m as __pageData,b as default};
